1	/* ===== Bộ điều khiển chế độ Trực tiếp / Mô phỏng (D-043, spec §4.4) =====
2	   Một chỗ duy nhất ghi số liệu thật vào cảnh. Trực tiếp: mỗi khung đặt dayNight.target theo độ cao mặt trời thật (solar.ts) và giữ `sun` cho applyNight;
3	   kho số liệu (store.ts) báo đổi thì tính đích thời tiết (envMap.ts) rồi weather.setLive(). Mô phỏng: không ghi gì (preset / cường độ / đêm của người xem giữ nguyên).
4	   Không import three / DOM: mọi phụ thuộc tiêm vào để chạy dưới Node (tests/live-unit/liveEnv.test.ts). Không cấp phát mỗi khung. */
5	import type { CONFIG } from '../config';
6	import type { WeatherParams } from '../environment/weather/state';
7	import type { EnvStore } from './store';
8	import { envToParams } from './envMap';
9	import { sunPosition, liveNight, sunWarm } from './solar';
10	
11	export type EnvMode = 'live' | 'manual';
12	export type LiveSun = { elev: number; azim: number; warm: number };   // cùng dạng SunOverride của core/dayNight.ts (không import để giữ module thuần)
13	export type LiveDeps = {
14	  cfg: typeof CONFIG.live; lat: number; lon: number;
15	  refreshMs: number;                                              // CONFIG.env.refreshMs: số liệu cũ hơn mức này thì làm mới khi vào Trực tiếp
16	  now: () => number;                                              // epoch ms (đã hiệu chỉnh: giờ máy + store.skew())
17	  clock?: () => number;                                           // ms đơn điệu cho cửa sổ áp tức thì (cfg.instantMs); không dùng now() vì skew có thể nhảy hàng giờ đúng lúc số liệu đầu tới. Mặc định Date.now
18	  store: Pick<EnvStore, 'data' | 'status' | 'onChange' | 'refresh'>;
19	  weather: { setLive(p: WeatherParams | null, instant?: boolean): void; stopScenario(): void; standTrees(): void };
20	  dayNight: { night: number; target: number };
21	  initial: EnvMode;
22	};
23	export type LiveEnv = {
24	  readonly mode: EnvMode; readonly sun: LiveSun | null;          // sun: null ở Mô phỏng ⇒ main.ts gọi applyNight như cũ
25	  setMode(m: EnvMode, why?: 'user' | 'feature'): void;            // 'feature': tính năng cần đêm tự chuyển sang Mô phỏng (giao diện hiện thông báo)
26	  update(dt: number): void;                                       // gọi mỗi khung TRƯỚC stepNight
27	  onChange(fn: (why: 'user' | 'feature' | 'data') => void): void;
28	};
29	
30	/** Thời gian chờ tới lần lấy số liệu kế tiếp ở Trực tiếp: mốc quan trắc obsStepMs kế tiếp (theo UTC) + obsDelayMs + nhiễu 0–jitterMs, không dưới minDelayMs.
31	    Mọi máy căn cùng mốc nên đổi số liệu gần như cùng lúc (spec §4.5). rnd: Math.random khi chạy thật (mỗi máy một nhiễu khác nhau, không phải ngẫu nhiên của cảnh nên
32	    không đụng chuỗi rand()); test tiêm nguồn tất định. */
33	export function liveNextDelay(now: number, cfg: { obsStepMs: number; obsDelayMs: number; jitterMs: number; minDelayMs: number }, rnd: () => number): number {
34	  const S = cfg.obsStepMs, at = (Math.floor((now - cfg.obsDelayMs) / S) + 1) * S + cfg.obsDelayMs;
35	  return Math.max(cfg.minDelayMs, at - now + rnd() * cfg.jitterMs);
36	}
37	
38	export function createLiveEnv(d: LiveDeps): LiveEnv {
39	  const cfg = d.cfg;
40	  let mode: EnvMode = d.initial;
41	  const sunObj: LiveSun = { elev: 0, azim: 180, warm: 0 };       // một đối tượng dùng lại (không cấp phát mỗi khung)
42	  let sun: LiveSun | null = null;
43	  let sunAt = -Infinity;                    // giờ (ms) của lần tính mặt trời gần nhất: tính lại khi lệch > 1 s (mặt trời đi 0,004°/s)
44	  let firstNight = mode === 'live';         // lần update đầu ở Trực tiếp lúc mở trang: gán luôn night = target (không chuyển cảnh)
45	  let applied = false;                      // đã áp số liệu lần nào chưa: lần đầu ở Trực tiếp lúc mở trang áp tức thì nếu tới trong cfg.instantMs
46	  const clock = d.clock || (() => Date.now()), born = clock();   // số liệu tới muộn (mạng chậm, người xem đã nhìn cảnh trung tính một lúc) thì tiến dần thay vì nhảy
47	  let lastData: unknown = null, lastUp: boolean | null = null;   // số liệu / ngày–đêm của lần setLive gần nhất (kho báo lỗi mà data giữ nguyên ⇒ không gọi lại)
48	  let manualTarget = d.dayNight.target;     // đêm đích của Mô phỏng, nhớ lúc rời Mô phỏng
49	  const subs: Array<(why: 'user' | 'feature' | 'data') => void> = [];
50	  const emit = (why: 'user' | 'feature' | 'data') => { for (const f of subs) { try { f(why); } catch (e) { console.error(e); } } };
51	
52	  const calcSun = (force: boolean) => {
53	    const t = d.now();
54	    if (!force && Math.abs(t - sunAt) <= 1000) return;
55	    sunAt = t;
56	    const p = sunPosition(t, d.lat, d.lon);
57	    sunObj.elev = p.elev; sunObj.azim = p.azim; sunObj.warm = sunWarm(p.elev, cfg.warm);
58	    sun = sunObj;
59	  };
60	  /* Số liệu → đích thời tiết. Chỉ ở Trực tiếp; data null (đang tải / mất mạng không đệm) ⇒ không gọi gì, giữ trạng thái cuối */
61	  const applyData = (instant: boolean) => {
62	    const data = d.store.data;
63	    if (mode !== 'live' || !data) return;
64	    const up = sunObj.elev > 0;
65	    if (data === lastData && up === lastUp) return;
66	    lastData = data; lastUp = up;
67	    d.weather.setLive(envToParams(data, up, cfg), instant);
68	    applied = true;
69	    emit('data');
70	  };
71	
72	  d.store.onChange(() => { if (mode === 'live') applyData(!applied && clock() - born <= cfg.instantMs); });
73	  if (mode === 'live') { calcSun(true); applyData(true); }       // kho có thể đã có số liệu (bộ nhớ đệm) trước khi bộ điều khiển được tạo
74	
75	  return {
76	    get mode() { return mode; },
77	    get sun() { return mode === 'live' ? sun : null; },
78	    setMode(m: EnvMode, why: 'user' | 'feature' = 'user') {
79	      if (m === mode) return;
80	      if (m === 'manual') {
81	        mode = 'manual'; firstNight = false;
82	        d.weather.setLive(null);
83	        d.dayNight.target = manualTarget;
84	        sun = null;
85	      } else {
86	        manualTarget = d.dayNight.target;
87	        mode = 'live'; firstNight = false; applied = true;   // từ Mô phỏng: cảnh tiến dần tới trạng thái thật (không tức thì)
88	        d.weather.stopScenario(); d.weather.standTrees();
89	        const data = d.store.data;
90	        if (!data || d.now() - data.obs > d.refreshMs) void d.store.refresh();
91	        calcSun(true);
92	        d.dayNight.target = liveNight(sunObj.elev, cfg);
93	        lastData = null; lastUp = null;
94	        applyData(false);
95	      }
96	      emit(why);
97	    },
98	    update(_dt: number) {
99	      // Không dùng dt: đêm tiến dần bằng stepNight, thời tiết bằng stepWeather (cả hai nhận dt đã kẹp trong animate); sau tab ẩn lâu đích đổi một lần rồi cảnh tiến dần
100	      if (mode !== 'live') return;
101	      calcSun(false);
102	      d.dayNight.target = liveNight(sunObj.elev, cfg);
103	      if (firstNight) { d.dayNight.night = d.dayNight.target; firstNight = false; }
104	      if (lastData && (sunObj.elev > 0) !== lastUp) applyData(false);   // qua chân trời: mù nóng chỉ ban ngày (envToParams sunUp)
105	    },
106	    onChange(fn) { subs.push(fn); }
107	  };
108	}
