1	import { t, onChange as onLangChange } from '../i18n';
2	import type { LiveEnv, EnvMode } from '../realtime/liveEnv';
3	import type { EnvStore } from '../realtime/store';
4	
5	/* ===== Giao diện hai chế độ Trực tiếp / Mô phỏng (D-043, spec §4.4) =====
6	   Chữ chế độ + chấm trong chỉ báo #envPill (#envMode), công tắc #envModeSw trong thẻ #envCard, dòng khóa #liveLock trong bảng Cài đặt, thông báo #liveNotice.
7	   Trực tiếp: thanh / nút Ngày–Đêm, ô chọn + thanh cường độ thời tiết, nút Kịch bản bão bị vô hiệu, và handler của chúng (setupUI.ts / weatherUI.ts) tự bỏ qua qua liveLocked().
8	   Tính năng cần ban đêm gọi liveYieldForNight() TRƯỚC khi ghi dayNight.target: đang Trực tiếp thì chuyển sang Mô phỏng ('feature') và hiện #liveNotice.
9	   Không có bộ điều khiển (liveEnv null, dựng lỗi): không gọi bindLiveMode ⇒ mọi phần tử trên giữ `hidden`, không khóa gì, như trước D-043. */
10	
11	let live: LiveEnv | null = null;
12	const LOCKED = ['timeSlider', 'btnNight', 'weatherSel', 'weatherK', 'btnWxStorm'];   // điều khiển mô phỏng thuần: vô hiệu ở Trực tiếp
13	
14	/** Đang Trực tiếp: điều khiển mô phỏng không được ghi gì */
15	export const liveLocked = (): boolean => !!live && live.mode === 'live';
16	/** Tính năng cần ban đêm (trình diễn Cầu Rồng, góc rfHearts / swNight, tour Vòng quay): đang Trực tiếp thì chuyển Mô phỏng trước khi ghi dayNight.target */
17	export function liveYieldForNight(): void { if (live && live.mode === 'live') live.setMode('manual', 'feature'); }
18	
19	export function bindLiveMode(le: LiveEnv, opts: { store: Pick<EnvStore, 'data' | 'onChange'>; syncSim: () => void; renderEnv: () => void }): void {
20	  live = le;
21	  const $ = (id: string) => document.getElementById(id);
22	  const env = $('env'), badge = $('envMode'), badgeTxt = badge?.querySelector<HTMLElement>('[data-mode-text]');
23	  const modes = $('envModes'), sw = $('envModeSw'), note = $('envModeNote');
24	  const btnL = $('envModeLive') as HTMLButtonElement | null, btnM = $('envModeManual') as HTMLButtonElement | null;
25	  const lock = $('liveLock'), lockTxt = lock?.querySelector<HTMLElement>('.live-lock-txt'), toManual = $('btnToManual'), toLive = $('btnToLive');
26	  const notice = $('liveNotice'), noticeLive = $('btnNoticeLive');
27	  for (const e of [badge, modes, lock]) if (e) e.hidden = false;
28	  const setText = (e: Element | null | undefined, s: string) => { if (e && e.textContent !== s) e.textContent = s; };
29	  /* Khám phá: Space / mũi tên là phím lái ⇒ bấm chuột xong thì bỏ focus khỏi #env / #liveLock (như blurInExplore của envUI.ts) */
30	  const blurInExplore = () => {
31	    const a = document.activeElement as HTMLElement | null;
32	    if (a && document.body.classList.contains('explore') && (env?.contains(a) || lock?.contains(a) || notice?.contains(a))) a.blur();
33	  };
34	
35	  const render = () => {
36	    const m: EnvMode = le.mode, on = m === 'live';
37	    if (env && env.dataset.mode !== m) env.dataset.mode = m;
38	    setText(badgeTxt, t(on ? 'liveBadge' : 'simBadge'));
39	    for (const [b, bm] of [[btnL, 'live'], [btnM, 'manual']] as const) {
40	      if (!b) continue;
41	      b.setAttribute('aria-checked', String(m === bm));
42	      b.tabIndex = m === bm ? 0 : -1;   // nhóm radio: Tab vào nút đang chọn, mũi tên đổi
43	    }
44	    setText(note, t(on ? (opts.store.data ? 'liveNoteLive' : 'liveNoData') : 'liveNoteManual'));
45	    if (lock) { lock.dataset.mode = m; if (lockTxt) lockTxt.hidden = !on; }
46	    if (toManual) toManual.hidden = !on;
47	    if (toLive) toLive.hidden = on;
48	    for (const id of LOCKED) { const c = $(id) as HTMLButtonElement | HTMLInputElement | HTMLSelectElement | null; if (c && c.disabled !== on) c.disabled = on; }
49	    opts.renderEnv();   // nhãn đọc màn hình của chỉ báo kèm chế độ (envUI.ts đọc #env[data-mode])
50	  };
51	
52	  /* Thông báo: tự ẩn sau 8 s; có nút "Về Trực tiếp" */
53	  let noticeTimer = 0;
54	  const hideNotice = () => { window.clearTimeout(noticeTimer); if (notice) notice.hidden = true; };
55	  const showNotice = () => { if (!notice) return; notice.hidden = false; window.clearTimeout(noticeTimer); noticeTimer = window.setTimeout(hideNotice, 8000); };
56	
57	  const go = (m: EnvMode) => { if (le.mode !== m) le.setMode(m, 'user'); };
58	  le.onChange((why) => {
59	    if (why === 'data') { setText(note, t(le.mode === 'live' ? (opts.store.data ? 'liveNoteLive' : 'liveNoData') : 'liveNoteManual')); return; }
60	    render();
61	    if (le.mode === 'manual') opts.syncSim();   // về Mô phỏng: thanh / ô chọn hiện lại đúng trạng thái mô phỏng đã nhớ
62	    if (why === 'feature') showNotice(); else if (le.mode === 'live') hideNotice();
63	  });
64	  opts.store.onChange(() => { if (le.mode === 'live') setText(note, t(opts.store.data ? 'liveNoteLive' : 'liveNoData')); });
65	  onLangChange(render);
66	
67	  btnL?.addEventListener('click', () => { go('live'); blurInExplore(); });
68	  btnM?.addEventListener('click', () => { go('manual'); blurInExplore(); });
69	  /* Bàn phím trong nhóm radio: mũi tên (cả hai chiều, chỉ hai lựa chọn nên RTL không đổi nghĩa) chọn + chuyển focus; Space / Enter chọn nút đang focus.
70	     stopPropagation: phím lái của khám phá (listener trên window) không nhận phím này; preventDefault: Space không cuộn trang */
71	  sw?.addEventListener('keydown', (e) => {
72	    const k = e.key;
73	    if (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'ArrowUp' || k === 'ArrowDown') {
74	      const m: EnvMode = le.mode === 'live' ? 'manual' : 'live';
75	      go(m); (m === 'live' ? btnL : btnM)?.focus();
76	    } else if (k === ' ' || k === 'Enter') {
77	      const b = (e.target as HTMLElement | null)?.closest<HTMLElement>('[data-mode-btn]');
78	      if (b) go(b.dataset.modeBtn as EnvMode);
79	    } else return;
80	    e.preventDefault(); e.stopPropagation();
81	  });
82	  // Nút vừa bấm bị ẩn (đổi chỗ với nút kia): đưa focus sang nút kia để bàn phím không rơi về <body>
83	  const swap = (m: EnvMode, next: HTMLElement | null) => () => { go(m); if (document.body.classList.contains('explore')) blurInExplore(); else next?.focus({ preventScroll: true }); };
84	  toManual?.addEventListener('click', swap('manual', toLive));
85	  toLive?.addEventListener('click', swap('live', toManual));
86	  noticeLive?.addEventListener('click', () => { go('live'); hideNotice(); blurInExplore(); });
87	  render();
88	}
