1	import * as THREE from 'three';
2	import { scene, renderer } from './renderer';
3	import { shared } from './shared';
4	import { MAT } from './materials';
5	import { sun, hemi, moon, bridgeLights } from './lights';
6	import { setSun, stars, clouds } from './sky';
7	import { water } from './water';
8	import { lerp, clamp } from '../common/math';
9	import { CONFIG } from '../config';
10	import { sunElevK } from '../realtime/solar';
11	
12	/* ============================ Ngày / đêm ============================ */
13	/* night: giá trị hiện tại (0 ngày → 1 đêm), target: giá trị người xem chọn; night tiến dần về target */
14	export const dayNight = { night: 0, target: 0 };
15	
16	const C_FOG_DAY = new THREE.Color(0xcfdde6), C_FOG_NIGHT = new THREE.Color(0x0b1424);
17	const C_HEMI_DAY = new THREE.Color(0xcfe6ff), C_HEMI_NIGHT = new THREE.Color(0x2a3a66);
18	const C_WATER_DAY = new THREE.Color(0x2c5a4f), C_WATER_NIGHT = new THREE.Color(0x08181b);
19	const C_BULB_DAY = new THREE.Color(0x9a9890), C_BULB_NIGHT = new THREE.Color(2.4, 1.9, 1.1);
20	
21	/* Mặt trời thật của chế độ Trực tiếp (D-043, realtime/liveEnv.ts): elev / azim độ (azim la bàn, 0 = Bắc, 90 = Đông), warm 0–1 (solar.ts sunWarm) */
22	export type SunOverride = { elev: number; azim: number; warm: number };
23	const C_SUN = sun.color.clone(), C_SUN_WARM = new THREE.Color(CONFIG.live.warmSun), C_FOG_WARM = new THREE.Color(CONFIG.live.warmFog);
24	let sunTinted = false;   // sun.color đang khác gốc (đã ở Trực tiếp): rời Trực tiếp thì trả lại một lần
25	
26	/* m: đêm 0–1. sun: bỏ trống / null = Mô phỏng, chạy y như trước D-043 (mặt trời cố định 205°, 40° → −7°) */
27	export function applyNight(m: number, time: number, so?: SunOverride | null) {
28	  shared.uNight.value = m;
29	  if (so) {
30	    // Đèn định hướng kẹp độ cao ≥ sunMinElev (bóng không dài vô hạn); bầu trời + phản chiếu nước nhận độ cao thật. Phương vị la bàn A ⇒ góc cảnh 180° − A (+X Đông, −Z Bắc)
31	    setSun(Math.max(so.elev, CONFIG.live.sunMinElev), 180 - so.azim, so.elev);
32	    // Hệ số theo độ cao luôn > 0: sun.intensity chỉ về 0 do `night` (≥ 0,87) như cũ, bộ đèn D-031 không đổi cách quyết
33	    sun.intensity = 3.0 * clamp(1 - m * 1.15, 0, 1) * sunElevK(so.elev);
34	    sun.color.copy(C_SUN).lerp(C_SUN_WARM, so.warm); sunTinted = true;
35	  } else {
36	    if (sunTinted) { sun.color.copy(C_SUN); sunTinted = false; }
37	    setSun(lerp(40, -7, m), 205);
38	    sun.intensity = 3.0 * clamp(1 - m * 1.15, 0, 1);
39	  }
40	  moon.intensity = 0.35 * m;
41	  hemi.intensity = lerp(0.9, 0.22, m);
42	  hemi.color.copy(C_HEMI_DAY).lerp(C_HEMI_NIGHT, m);
43	  (scene.fog as THREE.FogExp2).color.copy(C_FOG_DAY).lerp(C_FOG_NIGHT, m);
44	  if (so && so.warm > 0) (scene.fog as THREE.FogExp2).color.lerp(C_FOG_WARM, so.warm * CONFIG.live.warmFogK * (1 - m));   // sương ấm lúc mặt trời thấp; sunWarm liên tục nên không nhảy
45	  scene.environmentIntensity = lerp(1, 0.14, m);
46	  renderer.toneMappingExposure = lerp(0.55, 0.8, m);
47	  water.material.uniforms.waterColor.value.copy(C_WATER_DAY).lerp(C_WATER_NIGHT, m);
48	  water.material.uniforms.sunColor.value.setRGB(lerp(1, 0.25, m), lerp(1, 0.3, m), lerp(1, 0.45, m));
49	  stars.material.opacity = clamp((m - 0.4) / 0.6, 0, 1);
50	  clouds.material.opacity = lerp(0.85, 0.12, m);
51	  MAT.bulb.color.copy(C_BULB_DAY).lerp(C_BULB_NIGHT, m);
52	  MAT.pupil.emissiveIntensity = m * 2.5;
53	  MAT.eye.emissiveIntensity = 0.05 + m * 0.4;
54	  // Đèn dọc cầu nhấp nháy nhẹ theo sin(time)
55	  bridgeLights.forEach((l) => { l.intensity = l.userData.base * m * (0.82 + 0.18 * Math.sin(time * 2.2 + l.userData.phase)); });
56	}
57	/* Một bước chuyển ngày ↔ đêm mỗi khung hình */
58	export function stepNight(dt: number) {
59	  dayNight.night += (dayNight.target - dayNight.night) * Math.min(1, dt * 1.6);
60	  if (Math.abs(dayNight.target - dayNight.night) < 0.001) dayNight.night = dayNight.target;
61	}
