const srv = await serveDir('D:/2026 - Tuan/danang-vite/.worktrees/thoi-tiet-thuc/dist');
const browser = await launch();
const { page, errors } = await openApp(browser, srv.url + '?envmode=live', { width: 1280, height: 720 });
const U = (h, m) => Date.UTC(2026, 10, 15, h, m);
const W = (o) => ({ obs: 0, obsMin: 600, temp: 27, feels: 29, hum: 70, wind: 12, dir: 45, rain: 0, cloud: 5, uv: 5, code: 0, isDay: true, sunrise: 355, sunset: 1035, gust: 20, vis: 24000, rate: 0, ...o });
const cases = [
  ['1-trua-nang', U(5, 0), W({})],
  ['2-u-am', U(4, 0), W({ code: 3, cloud: 100, hum: 88 })],
  ['3-mua-to-dem', U(13, 0), W({ code: 65, cloud: 100, hum: 98, rate: 15, rain: 3.75, vis: 3000, wind: 30, gust: 50 })],
  ['4-suong', U(0, 30), W({ code: 45, cloud: 100, hum: 99, vis: 300, wind: 4, gust: 6 })],
  ['5-hoang-hon', U(10, 5), W({ cloud: 20 })],
  ['6-chang-vang', U(10, 30), W({ cloud: 20 })],
  ['7-nua-dem-quang', U(17, 0), W({ cloud: 10 })]
];
console.log('mode', await page.evaluate(() => window.__app.live && window.__app.live.mode));
for (const [name, t, wx] of cases) {
  const info = await page.evaluate(async ([t, wx]) => {
    const a = window.__app; wx.obs = t - 300000;
    a.env.setNow(() => t); a.env.store.inject(wx);
    await new Promise((r) => { let i = 0; const f = () => (++i > 3 ? r() : requestAnimationFrame(f)); requestAnimationFrame(f); });
    const s = a.weather.state; Object.assign(s.current, s.target); s.wet = s.target.rain; a.dayNight.night = a.dayNight.target;
    await new Promise((r) => { let i = 0; const f = () => (++i > 4 ? r() : requestAnimationFrame(f)); requestAnimationFrame(f); });
    const sun = a.live.sun, sc = a.scene;
    const cl = sc.getObjectByProperty('isInstancedMesh', true);
    return { sun: sun && { elev: +sun.elev.toFixed(1), azim: +sun.azim.toFixed(1), warm: +sun.warm.toFixed(2) }, night: a.dayNight.night, target: { ...s.target, windDir: +s.target.windDir.toFixed(2) }, fogD: sc.fog.density, fogC: sc.fog.color.getHexString(), lights: a.lights.set };
  }, [t, wx]);
  console.log(name, JSON.stringify(info));
  await frames(page, 3);
  await page.screenshot({ path: OUT + name + '.png' });
}
// rời Trực tiếp: phải trả về như cũ
const back = await page.evaluate(async () => {
  const a = window.__app; a.live.setMode('manual');
  await new Promise((r) => setTimeout(r, 400));
  const s = a.weather.state; Object.assign(s.current, s.target); s.wet = 0; a.dayNight.night = a.dayNight.target;
  await new Promise((r) => setTimeout(r, 2500));
  return { mode: a.live.mode, sun: a.live.sun, preset: s.preset, enabled: a.weather.enabled, live: a.weather.live, fogD: a.scene.fog.density, fogC: a.scene.fog.color.getHexString(), tau: s.tauScale, night: a.dayNight.night };
});
console.log('manual', JSON.stringify(back));
await page.screenshot({ path: OUT + '8-ve-mo-phong.png' });
console.log('errors', errors);
await browser.close(); srv.close();
