export function buildHearts(towers: Tower[]): Hearts {
  const geos: THREE.BufferGeometry[] = [], panels: Hearts['panels'] = [];
  const Hh = Math.min(...towers.map((t) => t.h)) * HC.panelFrac, pw = HC.panelW;
  const phases: number[] = [];
